import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root object (position/rotation/scale will be applied by the adapter)
  const root = new Group();

  // --- Plane with texture -------------------------------------------------
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });
  const plane = new Mesh(geometry, material);
  // Slight offset so text can sit above without z‑fighting
  plane.position.z = 0;

  root.add(plane);

  // Load texture asynchronously; keep reference for cleanup
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text label ---------------------------------------------------------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    // Expected shape: { text: string, role?: string, typography?: { fontSize?: number } }
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: (item.typography && item.typography.fontSize) || 39,
      color: config.visual?.colors?.paper ?? '#e8ecf2',
      align: 'center',
      maxWidthPx: 512,
    });
    // Center text on the plane, raise a bit to avoid z‑fighting
    txt.position.z = 0.001;
    root.add(txt);
  }

  // --- Event handlers placeholder -----------------------------------------
  root.userData.handlers = {};

  // --- Cleanup -------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture if present
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }

    // Kill any GSAP timelines (none attached here but safe)
    gsap.globalTimeline.kill();
  };

  return root;
}
